import { parseBotMd } from '@manythreads/shared';
import { describe, expect, it } from 'vitest';
import { frontmatterScalarProblems, oneLineProblem, renderBotMd } from '../src/frontmatter.ts';

// P7-04 follow-up (found live): a role written unquoted with `#dev` in it was stored cut at the #. The name and the role are generated by the platform and every sentence line is read back.

const bot = (role: string, name = 'Reviewer'): string => `---
schema: 1
name: ${name}
role: ${role}
kind: agent
runtime: hermes
model:
  aliases: [smart]
triggers:
  - type: mention
capabilities:
  native: [messages.post]
---

Do the work.
`;

const AWKWARD = [
  'Reads new pull request posts in #dev and replies',
  'Answers: politely, then asks: what next?',
  'Says "hello" and \'goodbye\' to people',
  '- starts with a dash',
  '* starts with a star',
  '> starts with a greater-than',
  '& starts with an ampersand',
  '! starts with a bang',
  '% starts with a percent',
  '@ starts with an at sign',
  '`starts with a backtick`',
  '[brackets] and {braces}',
  'ends with a colon:',
  'Antwortet auf Fragen zur Veröffentlichung, auch auf Deutsch: Größe, Grüße ✓ 日本語 ‏العربية',
  'yes',
  'null',
  '123',
  '  padded with spaces  ',
  'back\\slash and \\n literal',
];

describe('renderBotMd writes the name and the role itself', () => {
  for (const role of AWKWARD) {
    it(`stores exactly: ${role.slice(0, 40)}`, () => {
      // even when the model's own line for it is unreadable YAML
      const r = renderBotMd(bot(role.includes('"') ? 'x' : role), { name: 'Release helper', role });
      expect(r.ok, r.ok ? '' : r.message).toBe(true);
      if (!r.ok) return;
      const back = parseBotMd(r.botMd);
      expect(back.ok).toBe(true);
      if (back.ok) {
        expect(back.frontmatter.role).toBe(role.trim());
        expect(back.frontmatter.name).toBe('Release helper');
        expect(back.frontmatter.kind).toBe('agent');
        expect(back.frontmatter.capabilities?.native).toEqual(['messages.post']);
        expect(back.body.trim()).toBe('Do the work.');
      }
    });
  }

  it('awkward names are stored exactly too', () => {
    for (const name of ['Dev #1 helper', 'Q&A: the bot', '- Sam\'s "bot"', 'Zoë 日本語']) {
      const r = renderBotMd(bot('Fine role'), { name, role: 'Fine role' });
      expect(r.ok, r.ok ? '' : r.message).toBe(true);
      const back = r.ok ? parseBotMd(r.botMd) : null;
      expect(back?.ok && back.frontmatter.name).toBe(name);
    }
  });

  it('a name or a role on more than one line is refused with a plain reason', () => {
    expect(oneLineProblem('role', 'one\ntwo', 200)).toMatch(/one line/);
    expect(renderBotMd(bot('x'), { name: 'Two\nlines', role: 'ok' }).ok).toBe(false);
    expect(renderBotMd(bot('x'), { name: 'Ok', role: 'a\u2028b' }).ok).toBe(false);
    expect(renderBotMd(bot('x'), { name: 'Ok', role: 'x'.repeat(201) }).ok).toBe(false);
    expect(renderBotMd(bot('x'), { name: '  ', role: 'ok' }).ok).toBe(false);
  });

  it('a multi-line role in the model\'s own text is replaced, with its continuation lines', () => {
    const text = bot('Reads posts\n  and replies to them');
    const r = renderBotMd(text, { name: 'Reviewer', role: 'Reads posts and replies to them' });
    expect(r.ok, r.ok ? '' : r.message).toBe(true);
    const back = r.ok ? parseBotMd(r.botMd) : null;
    expect(back?.ok && back.frontmatter.role).toBe('Reads posts and replies to them');
    expect(back?.ok && back.frontmatter.runtime).toBe('hermes');
  });

  it('without a role it leaves the role line alone', () => {
    const r = renderBotMd(bot('"Kept role"'), { name: 'New name' });
    const back = r.ok ? parseBotMd(r.botMd) : null;
    expect(back?.ok && back.frontmatter.role).toBe('Kept role');
    expect(back?.ok && back.frontmatter.name).toBe('New name');
  });

  it('a block that does not load is reported, not repaired', () => {
    const r = renderBotMd('no front matter', { name: 'A', role: 'B' });
    expect(r).toMatchObject({ ok: false });
  });
});

describe('frontmatterScalarProblems reads each sentence line back', () => {
  it('the live failure: `#dev` turns the rest of the line into a comment', () => {
    const problems = frontmatterScalarProblems(bot('Reads new pull request posts in #dev and replies'));
    expect(problems).toHaveLength(1);
    expect(problems[0]).toMatch(/role/);
    expect(problems[0]).toMatch(/comment/);
    expect(problems[0]).toMatch(/double quotes/);
  });

  it('a line in quotes, and a plain line that means what it says, are fine', () => {
    expect(frontmatterScalarProblems(bot('"Reads new posts in #dev and replies"'))).toEqual([]);
    expect(frontmatterScalarProblems(bot('Reads new posts and replies, politely.'))).toEqual([]);
    expect(frontmatterScalarProblems(bot("'It''s fine: really #1'"))).toEqual([]);
    expect(frontmatterScalarProblems(bot('Reads posts. A trailing hash# is no comment.'))).toEqual([]);
  });

  it('a name or role that YAML reads as something other than text is refused', () => {
    expect(frontmatterScalarProblems(bot('123'))[0]).toMatch(/does not read as text/);
    expect(frontmatterScalarProblems(bot('true'))[0]).toMatch(/does not read as text/);
    expect(frontmatterScalarProblems(bot('~'))[0]).toMatch(/empty/);
    expect(frontmatterScalarProblems(bot('Fine', '2024'))[0]).toMatch(/name/);
  });

  it('a block of text (`role: >` or `role: |`) is refused in plain words: the text sits on other lines and is folded', () => {
    for (const marker of ['>', '|', '>-', '|-', '>+']) {
      const md = bot(marker).replace(`role: ${marker}`, `role: ${marker}\n  Answers questions about the release\n  checklist and nothing else.`);
      const problems = frontmatterScalarProblems(md);
      expect(problems, marker).toHaveLength(1);
      expect(problems[0]).toMatch(/"role:" is a block of text/);
      expect(problems[0]).toMatch(/one line, in double quotes/);
    }
    // the text on the lines under a bare `role:` is the same trouble
    const bare = bot('x').replace('role: x', 'role:\n  Answers questions about the release');
    expect(frontmatterScalarProblems(bare)[0]).toMatch(/text on the lines below/);
    // the same marker in a line that is not a sentence line is not this check's business
    expect(frontmatterScalarProblems(bot('Fine'))).toEqual([]);
  });

  it('a hidden line break (U+2028, U+2029, U+0085) or a control character is refused, quoted or not, written out or as an escape', () => {
    for (const ch of ['\u2028', '\u2029', '\u0085', '\u0007']) {
      expect(frontmatterScalarProblems(bot(`Answers questions.${ch}Then stops.`))[0], JSON.stringify(ch)).toMatch(/hidden line break or control character/);
      expect(frontmatterScalarProblems(bot(`"Answers questions.${ch}Then stops."`))[0], JSON.stringify(ch)).toMatch(/hidden line break or control character/);
    }
    expect(frontmatterScalarProblems(bot('"Answers questions.\\u2028Then stops."'))[0]).toMatch(/hidden line break or control character/);
    expect(frontmatterScalarProblems(bot('"Answers questions.\\u2029Then stops."'))[0]).toMatch(/hidden line break or control character/);
    // a plain tab inside a sentence is only a space
    expect(frontmatterScalarProblems(bot('"Answers\tquestions."'))).toEqual([]);
  });

  it('a name cut by a comment is found too', () => {
    expect(frontmatterScalarProblems(bot('Fine', 'Helper #2'))[0]).toMatch(/"name:"/);
  });

  it('text that is not a BOT.md, or whose block does not parse, is the loader\'s to report', () => {
    expect(frontmatterScalarProblems('hello')).toEqual([]);
    expect(frontmatterScalarProblems('---\nrole: [unclosed\n---\n')).toEqual([]);
  });
});
